    xml.write_attribute(
        "transform",
        &format!("matrix(1 0 0 -1 {} {})", fmt_num(pos.x.0), fmt_num(pos.y.0)),
    );

    let fill = style
        .fill
        .clone()
        .map(color_to_css)
        .unwrap_or_else(|| "#000000".to_string());
    let mut x = 0.0;
    let y = 0.0;
    for glyph in glyphs {
        let x_offset = f64::from(glyph.x_offset) * scale;
        let y_offset = f64::from(glyph.y_offset) * scale;
